import json, sys, os
from collections import defaultdict
sys.path.insert(0, 'commons/tools')
import swarmlib

# 统计每个代理创建的工件数
artifacts = defaultdict(int)
for subdir in ['tools', 'findings', 'data', 'challenges', 'builds']:
    d = os.path.join(swarmlib.COMMONS, subdir)
    if not os.path.exists(d):
        continue
    for f in os.listdir(d):
        if f.startswith('agent-'):
            aid = f.split('_')[0]
            artifacts[aid] += 1

# 统计每个代理被引用的次数
ledger_raw = swarmlib.read_jsonl(swarmlib.CITATIONS)
all_entries = []
for entry in ledger_raw:
    if isinstance(entry, list):
        all_entries.extend(entry)
    else:
        all_entries.append(entry)

citations_received = defaultdict(int)
citations_given = defaultdict(int)
for entry in all_entries:
    if not isinstance(entry, dict):
        continue
    citer = entry.get('citer', '')
    cited = str(entry.get('cited', ''))
    if citer.startswith('agent-'):
        citations_given[citer] += 1
    # extract agent id from cited
    if 'agent-' in cited:
        import re
        m = re.search(r'agent-\d+', cited)
        if m:
            citations_received[m.group()] += 1

print('=== Top agents by artifacts ===')
for aid, count in sorted(artifacts.items(), key=lambda x: -x[1])[:15]:
    cites = citations_received.get(aid, 0)
    print(f'  {aid:12s}  {count:3d} artifacts  {cites:3d} citations received')

print()
print('=== Top agents by citations received ===')
for aid, count in sorted(citations_received.items(), key=lambda x: -x[1])[:15]:
    arts = artifacts.get(aid, 0)
    print(f'  {aid:12s}  {count:3d} citations  {arts:3d} artifacts')
